  if(device < 0 || cudaGetDeviceCount(&deviceCount) != cudaSuccess || device >= deviceCount)
    return nullptr;

  int previousDevice = 0;
  if(cudaGetDevice(&previousDevice) != cudaSuccess || cudaSetDevice(device) != cudaSuccess)
    return nullptr;
