  context->device = device;
  context->loaded = false;
  katago_sm103_b29_cudnn_swiglu_Kernel_Module_Load(&context->module);
  context->loaded = context->module.module != nullptr;
  cudaSetDevice(previousDevice);
  if(!context->loaded) {
    delete context;
    setStatus(status,KATAGO_CUDNN_OSS_B29_MODULE_LOAD_FAILED);
    return nullptr;
  }
  setStatus(status,KATAGO_CUDNN_OSS_B29_SUCCESS);
